/**
 * The surfacer is a READER over lib/debt-ledger (#3708). These tests pin the
 * rendering contract; the cache, HEAD key, lock and scan live in
 * lib/debt-ledger.test.ts.
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { mockCommonBasic } from '../fixtures/mock-common.js';

const mockLoad = vi.fn();
vi.mock('../../lib/debt-ledger.js', () => ({
  loadOrBuildLedger: (...args: unknown[]) => mockLoad(...args),
}));

const mockGetProjectDir = vi.fn(() => '/proj');
vi.mock('../../lib/paths.js', () => ({
  getProjectDir: () => mockGetProjectDir(),
}));

vi.mock('../../lib/common.js', () => mockCommonBasic());

import { debtSurfacer } from '../../instructions-loaded/debt-surfacer.js';

function ledger(entries: Array<Record<string, unknown>>, source = 'cache') {
  return { ledger: { version: 1, head: 'abc', generated_at: new Date().toISOString(), entries }, source };
}

describe('debtSurfacer', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    delete process.env.ORK_DISABLE_DEBT_SURFACER;
    mockGetProjectDir.mockReturnValue('/proj');
  });

  it('returns null when the ledger has no entries', () => {
    mockLoad.mockReturnValue(ledger([]));
    expect(debtSurfacer([], new Map())).toBeNull();
  });

  it('returns null when no ledger could be served (locked, no cache)', () => {
    mockLoad.mockReturnValue({ ledger: null, source: 'locked' });
    expect(debtSurfacer([], new Map())).toBeNull();
  });

  it('surfaces a compact ledger summary', () => {
    mockLoad.mockReturnValue(
      ledger([
        { file: 'src/auth.ts', line: 14, choice: 'session cookies', upgrade: 'JWT', trigger: 'a 2nd service is added' },
        { file: 'src/db.ts', line: 8, choice: 'SQLite', upgrade: 'Postgres', trigger: 'writers > 1' },
      ]),
    );
    const out = debtSurfacer([], new Map());
    expect(out).not.toBeNull();
    expect(out).toContain('[Deferred Debt]');
    expect(out).toContain('2 deliberate shortcut(s) tracked across 2 file(s)');
    expect(out).toContain('src/auth.ts:14');
    expect(out).toContain('session cookies -> JWT');
    expect(out).toContain('src/db.ts:8');
    expect(mockLoad).toHaveBeenCalledWith('/proj');
  });

  it('serves a HEAD-old ledger the same as a fresh one (advisory banner)', () => {
    mockLoad.mockReturnValue(ledger([{ file: 'a.ts', line: 1, choice: 'x', upgrade: 'y', trigger: 'z' }], 'stale'));
    expect(debtSurfacer([], new Map())).toContain('1 deliberate shortcut(s)');
  });

  it('caps the listed markers and notes the remainder', () => {
    const entries = Array.from({ length: 8 }, (_, i) => ({
      file: `src/f${i}.ts`, line: i + 1, choice: `shortcut ${i}`, upgrade: `fix ${i}`, trigger: `cond ${i}`,
    }));
    mockLoad.mockReturnValue(ledger(entries));
    const out = debtSurfacer([], new Map()) ?? '';
    expect(out).toContain('8 deliberate shortcut(s)');
    expect(out).toContain('...and 3 more');
  });

  it('respects the opt-out env var without touching the ledger', () => {
    process.env.ORK_DISABLE_DEBT_SURFACER = '1';
    expect(debtSurfacer([], new Map())).toBeNull();
    expect(mockLoad).not.toHaveBeenCalled();
  });
});
